$translations = [];
foreach ($pages as $language => $sections) {
    foreach ($sections as $key => $texts) {
        $translations[$language]['rb'.$key.'Title'] = $texts[0];
        $translations[$language]['rb'.$key.'Caption'] = $texts[1];
        foreach (array_slice($texts, 2) as $index => $text) {
            $translations[$language]['rb'.$key.'Step'.($index + 1)] = $text;
        }
    }
}
return $translations;
